# Frayd bootstrap (Windows) — generated by the web installer.
# Args: LIBRARY_PATH
param([string]$Lib = "")
$ErrorActionPreference = "Stop"

Write-Host "== Frayd installer =="
Write-Host "Media folder: $(if ($Lib) { $Lib } else { '<unset>' })"

# --- deps ---
if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
  Write-Host "[!] git is required: https://git-scm.com/download/win"; exit 1
}
if (-not (Get-Command ffmpeg -ErrorAction SilentlyContinue)) {
  Write-Host "[*] Installing ffmpeg via winget..."
  winget install -e --id Gyan.FFmpeg --accept-source-agreements --accept-package-agreements 2>$null
}

# --- rust ---
if (-not (Get-Command cargo -ErrorAction SilentlyContinue)) {
  Write-Host "[*] Installing Rust toolchain..."
  Invoke-WebRequest https://win.rustup.rs/x86_64 -OutFile "$env:TEMP\rustup-init.exe"
  & "$env:TEMP\rustup-init.exe" -y --default-toolchain stable
  $env:PATH = "$env:USERPROFILE\.cargo\bin;$env:PATH"
}

# --- clone / update ---
Set-Location $env:USERPROFILE
if (Test-Path Frayd) { Push-Location Frayd; git pull --ff-only; Pop-Location }
else { git clone https://github.com/kattiest/Frayd.git }

# --- library path ---
if (-not $Lib) {
  $Lib = Read-Host "Path to your media folder [$env:USERPROFILE\Media]"
  if (-not $Lib) { $Lib = "$env:USERPROFILE\Media" }
}
New-Item -ItemType Directory -Force -Path $Lib | Out-Null

# --- build ---
Write-Host "[*] Building (first build takes a few minutes)..."
Set-Location Frayd\server
cargo build --release

# --- env file ---
"FRAYD_LIBRARY=$Lib" | Out-File -Encoding utf8 .env

# --- autostart: Startup folder shortcut (no admin needed) ---
$startup = [Environment]::GetFolderPath("Startup")
$bat = Join-Path $startup "frayd.bat"
@"
@echo off
cd /d "$PWD"
set /p FRAYD_LIBRARY=<.env
start /b "" "$PWD\target\release\frayd-server.exe"
"@ -replace 'set /p FRAYD_LIBRARY=<\.env', "for /f `"usebackq tokens=*`" %%a in (`".env`") do set %%a" | Out-File -Encoding ascii $bat

Write-Host ""
Write-Host "[OK] Frayd installed. Starting now..."
Start-Process -FilePath "$PWD\target\release\frayd-server.exe" -WindowStyle Hidden
Write-Host "[OK] Runs at startup. Open http://localhost:8484"
Write-Host "     First login becomes the admin account."
